import logging
import pexpect
import queue
from select import select
from threading import Thread
from taf.internal.execution.base import Process, InputStream, OutputStream, TimeoutError


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class LocalPtyProcess(Process):
    def __init__(
            self,
            pty_process,
            **kwargs):
        """
        Create a local process, which uses a terminal.

        :param PtyProcess pty_process: process with a terminal
        """
        super(LocalPtyProcess, self).__init__(**kwargs)
        self._pty_process = pty_process
        self._wait_queue = None
        self._exit_status = None

    def wait(self, timeout=None):
        """
        Wait until the process finishes execution.

        :param float timeout:
            wait timeout seconds for the process to finish
            (forever, if timeout is None)
        :raises: TimeoutError, if process did not finish after timeout seconds
        """
        if self._wait_queue is None:
            self._wait_queue = self._create_wait_queue()
        try:
            self._exit_status = self._wait_queue.get(block=True, timeout=timeout)
        except queue.Empty:
            raise TimeoutError(self._command, timeout)

    def _create_wait_queue(self):
        wait_queue = queue.Queue()

        def run():
            wait_queue.put(self._pty_process.wait())

        thread = Thread(target=run)
        thread.daemon = True
        thread.start()
        return wait_queue

    def _get_is_running(self):
        """
        Return True, if the process is still running.

        :return:
        """
        return self._pty_process.isalive()

    def _get_exit_status(self):
        """
        Return the exit status of a terminated process.

        :return: exit status
        :rtpye: int
        """
        return self._exit_status

    def _read_output(self):
        """
        Read stdout from the process without logging.

        :return: stdout data, stderr data (empty)
        :rtype: bytes, bytes
        """
        stdout_fd = self._pty_process.child_fd
        stdout_data = bytearray()

        while True:
            rlist, _, _ = select([stdout_fd], [], [], None)
            if stdout_fd in rlist:
                data = self.stdout.read(4096)
                if not data:
                    break
                stdout_data.extend(data)

        return bytes(stdout_data), b""


class LocalPtyStream(object):
    """
    Base class of input and output streams of a local process with a terminal.
^   """

    def __init__(self, pty_process, **kwargs):
        """
        Create a LocalPtyStream.

        :param LocalPtyProcess pty_process: local process with a terminal
        """
        super(LocalPtyStream, self).__init__(**kwargs)
        self._pty_process = pty_process


class LocalPtyInputStream(LocalPtyStream, InputStream):
    """
    Input stream of a local process with a terminal.
    """

    def write(self, data):
        """
        Write data to stream.

        :param bytes data: data to be written into the input stream
        """
        logger.debug("writing {data!r} to input stream".format(data=data))
        total_bytes = remaining_bytes = len(data)
        while remaining_bytes > 0:
            new_data = data[total_bytes - remaining_bytes:]
            written_bytes = self._pty_process.send(new_data.decode("cp437"))
            remaining_bytes -= written_bytes
            logger.debug("wrote {written_bytes} bytes to input stream".format(written_bytes=written_bytes))

    def close(self):
        """
        Close the input stream.
        """
        logger.debug("closing")
        self._pty_process.send("\x04")
        self._pty_process.flush()


class LocalPtyOutputStream(LocalPtyStream, OutputStream):
    """
    Output stream of a local process with a terminal.
    """

    _stream_name = "stdout"

    def _read(self, size=None, timeout=None):   # noqa: C901
        """
        Read data from stream.

        :param int size: maximum number of bytes to read (read all data, if size is None)
        :param float timeout: timeout in seconds to wait for the next character

        :return: read data
        :rtype: bytes
        """
        if size is None:
            data = b""
            while True:
                try:
                    new_data = self._pty_process.read_nonblocking(size=1024, timeout=timeout)
                    new_data = new_data.encode("cp437")
                except pexpect.EOF:
                    new_data = b""
                except pexpect.TIMEOUT:
                    raise TimeoutError()
                if not new_data:
                    return data
                data += new_data
        else:
            try:
                data = self._pty_process.read_nonblocking(size=size, timeout=timeout)
                data = data.encode("cp437")
            except pexpect.EOF:
                data = b""
            except pexpect.TIMEOUT:
                raise TimeoutError()
            return data


class LocalPtyErrorStream(LocalPtyStream, OutputStream):
    """
    Error stream of a local process with a terminal.
    """

    _stream_name = "stderr"

    def _read(self, size=None, timeout=None):
        """
        Read data from stream.

        :param int size: maximum number of bytes to read (read all data, if size is None)
        :param float timeout: timeout in seconds to wait for the next character

        :return: read data
        :rtype: bytes
        """
        return b""
